export function validateConfig(input,current){const c={...current};const bounds={minCap:[50e6,500e6],primaryCap:[500e6,3e9],maxCap:[1e9,5e9],minPrice:[1,20],minDollarVolume:[1e6,20e6],maxSpread:[.1,2],dailyBudget:[.1,10],riskPct:[.1,2],maxEntries:[1,2],maxPositions:[1,20],horizonDays:[7,45]};for(const [k,v] of Object.entries(input)){if(!bounds[k]||!Number.isFinite(v)||v<bounds[k][0]||v>bounds[k][1])throw Error('Configuración fuera de límites');if(['maxEntries','maxPositions','horizonDays'].includes(k)&&!Number.isInteger(v))throw Error('Valor entero requerido');c[k]=v;}if(c.minCap>=c.primaryCap||c.primaryCap>c.maxCap)throw Error('Rangos de capitalización inválidos');return c;}
